rounds.cypher:
// Round 1: open issues by business unit and rating
MATCH (i:Issue)-[:AGAINST]->(:Risk)<-[:EXPOSED_TO]-(:AuditableEntity)<-[:OWNS]-(b:BusinessUnit)
WHERE i.closed_date IS NULL
RETURN b.id AS business_unit_id, b.name AS business_unit_name, i.rating AS rating,
  count(DISTINCT i) AS open_issues
ORDER BY business_unit_id, rating;

// Round 2: High canonical risks with stale coverage
MATCH (c:CanonicalRisk)<-[:MAPS_TO]-(r:Risk)
WITH c, collect(r) AS members
WHERE any(m IN members WHERE m.inherent_rating = 'High')
  AND NOT EXISTS {
    MATCH (c)<-[:MAPS_TO]-(:Risk)<-[:MITIGATES]-(:Control)<-[:TESTED]-(a:Audit)
    WHERE a.end_date >= $cutoff }
RETURN c.id AS canonical_risk_id,
  CASE WHEN any(m IN members WHERE m.source = 'IA') THEN 'Y' ELSE 'N' END AS has_ia_member
ORDER BY canonical_risk_id;

// Round 3: shared-system blast radius
MATCH (s:System)<-[:DEPENDS_ON]-(:Control)-[:MITIGATES]->(:Risk)<-[:EXPOSED_TO]-(e:AuditableEntity)
RETURN s.id AS system_id, s.name AS system_name, count(DISTINCT e) AS entities
ORDER BY entities DESC, system_name
LIMIT 3;

// Round 4: every path from a regulation to a business unit
MATCH (g:Regulation)-[:REQUIRES]->(:Control)-[:MITIGATES]->(:Risk)
  <-[:EXPOSED_TO]-(:AuditableEntity)<-[:OWNS]-(b:BusinessUnit)
RETURN g.id AS regulation_id, b.id AS business_unit_id, count(*) AS paths
ORDER BY regulation_id, business_unit_id;

// Round 5 setup: vendors become nodes, and the fourth-party register becomes edges
MATCH (s:System)
MERGE (v:Vendor {name: s.vendor})
CREATE (s)-[:SUPPLIED_BY]->(v);
UNWIND $rows AS row
MERGE (a:Vendor {name: row.vendor})
MERGE (b:Vendor {name: row.relies_on})
CREATE (a)-[:RELIES_ON]->(b);

// Round 5: entities exposed to a vendor, directly or through fourth parties
MATCH p = (e:AuditableEntity)-[:PERFORMS]->(:Process)-[:RUNS_ON]->(:System)
  -[:SUPPLIED_BY]->(:Vendor)-[:RELIES_ON*0..]->(:Vendor {name: $vendor})
RETURN e.id AS auditable_entity_id,
  CASE WHEN min(length(p)) = 3 THEN 'direct' ELSE 'fourth_party_only' END AS exposure
ORDER BY auditable_entity_id;

supporting.cypher:
// Supporting query: owner concentration of key controls
MATCH (p:Person)<-[:OWNED_BY]-(c:Control {key_control: 'Y'})
OPTIONAL MATCH (c)-[:MITIGATES]->(:Risk)<-[:EXPOSED_TO]-(:AuditableEntity)<-[:OWNS]-(b:BusinessUnit)
RETURN p.id AS person_id, count(DISTINCT c) AS key_controls, count(DISTINCT b) AS business_units
ORDER BY key_controls DESC, business_units DESC, person_id
LIMIT 10;
